import json, subprocess, warnings
warnings.filterwarnings("ignore")
from TTS.utils.synthesizer import Synthesizer
lines = [
 "हमेशा थकान? वज़न बढ़ता जा रहा है? बाल झड़ रहे हैं? हो सकता है वजह आपका थायरॉइड हो! आज बुधवार की हेल्थ टिप में जानिए थायरॉइड टेस्ट. आखिर तक देखिए.",
 "थायरॉइड गले में एक छोटी सी तितली जैसी ग्रंथि है. यह शरीर की स्पीड कंट्रोल करती है. ऊर्जा, वज़न, दिल की धड़कन, और मूड, सब पर इसका असर होता है.",
 "थायरॉइड दो तरह से गड़बड़ हो सकता है. कम काम करे, तो हाइपोथायरॉइड. थकान, वज़न बढ़ना, ठंड लगना, बाल झड़ना, कब्ज़. ज़्यादा काम करे, तो हाइपरथायरॉइड. वज़न घटना, तेज़ धड़कन, पसीना, हाथ कांपना, और घबराहट.",
 "भारत में लगभग हर दस में से एक बड़े व्यक्ति को हाइपोथायरॉइड है. महिलाओं में यह ज़्यादा होता है. और बहुत से लोगों को पता ही नहीं होता.",
 "टेस्ट बहुत आसान है, बस एक खून का सैंपल. टी एस एच, दिमाग से आने वाला सिग्नल. टी थ्री और टी फोर, थायरॉइड के हार्मोन. याद रखिए, टी एस एच ज़्यादा, तो आमतौर पर थायरॉइड धीमा. टी एस एच कम, तो थायरॉइड तेज़.",
 "किसे जांच करानी चाहिए? पैंतीस साल से ऊपर की महिलाएं. प्रेग्नेंसी की प्लानिंग या प्रेग्नेंसी में. डिलीवरी के बाद. परिवार में थायरॉइड हो. डायबिटीज़, पी सी ओ डी, या पीरियड्स अनियमित हों. और नवजात शिशु की थायरॉइड जांच के बारे में, डॉक्टर से ज़रूर पूछें.",
 "टेस्ट की तैयारी. आमतौर पर खाली पेट की ज़रूरत नहीं. सुबह का सैंपल बेहतर. अगर थायरॉइड की गोली लेते हैं, तो डॉक्टर की सलाह के अनुसार, सैंपल गोली से पहले दें. और बायोटिन सप्लीमेंट लेते हों, तो डॉक्टर को ज़रूर बताएं.",
 "मिथक, अच्छा महसूस हो तो गोली बंद कर दो. सच, गोली कभी भी खुद से बंद न करें, न डोज़ बदलें. टी एस एच दोबारा कब जांचना है, यह डॉक्टर बताएंगे.",
 "याद रखें, कोई भी दवा सिर्फ डॉक्टर की सलाह से ही लें. क्या आपने कभी थायरॉइड टेस्ट करवाया है? कमेंट में बताइए, और शेयर करें. और ज़्यादा जानकारी के लिए, हमारा फेसबुक पेज और यूट्यूब चैनल फॉलो करें. हेल्थ टेस्ट सिम्प्लिफाइड.",
]
import os
d = os.environ.get("HTS_MODEL", "/tmp/hi/hi/")
s = Synthesizer(tts_checkpoint=d + "fastpitch/best_model.pth", tts_config_path=d + "fastpitch/config.json",
                vocoder_checkpoint=d + "hifigan/best_model.pth", vocoder_config=d + "hifigan/config.json", use_cuda=False)
durs = []
for i, l in enumerate(lines):
    f = f"/tmp/tyr_{i}.wav"; s.save_wav(s.tts(l, speaker_name="female"), f)
    subprocess.run(["ffmpeg","-nostdin","-y","-loglevel","error","-i",f,"-af","rubberband=pitch=0.96:formant=preserved,equalizer=f=250:t=q:w=1:g=2,treble=g=-1.5:f=6000",f"/tmp/ty_{i}.wav"],check=True); f=f"/tmp/ty_{i}.wav"
    durs.append(float(subprocess.check_output(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", f]).decode()))
json.dump(durs, open("/tmp/ty_durs.json", "w")); print([round(x, 1) for x in durs], round(sum(durs), 1))
